<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';

type AdminUser = { id:number; name:string; username:string; email:string; role:string; is_active:boolean; must_change_password:boolean; last_login_at:string|null };
const props = defineProps<{ users: AdminUser[] }>();
const page = usePage();
const flash = computed(() => (page.props as { flash?: { success?: string } }).flash);
const roles = ['super_admin', 'admin_pmb', 'finance', 'reviewer', 'viewer'];
const roleLabels: Record<string,string> = { super_admin:'Super admin', admin_pmb:'Admin PMB', finance:'Keuangan', reviewer:'Peninjau', viewer:'Pembaca' };
const form = useForm({ name:'', username:'', email:'', role:'viewer', password:'', password_confirmation:'' });
const showPassword = ref(false);
const showConfirmation = ref(false);
const savingUserId = ref<number|null>(null);
const hasFormErrors = computed(() => Object.keys(form.errors).length > 0);
const submit = () => form.post('/admin/users', { preserveScroll:true, onSuccess:() => { form.reset(); form.role='viewer'; showPassword.value=false; showConfirmation.value=false; } });
const resetForm = () => { form.reset(); form.clearErrors(); form.role='viewer'; showPassword.value=false; showConfirmation.value=false; };
const update = (user:AdminUser) => { savingUserId.value=user.id; router.patch(`/admin/users/${user.id}`, { name:user.name, username:user.username, role:user.role, is_active:user.is_active }, { preserveScroll:true, onFinish:() => { savingUserId.value=null; } }); };
const formatDate = (value:string|null) => value ? new Intl.DateTimeFormat('id-ID', { dateStyle:'medium', timeStyle:'short' }).format(new Date(value)) : 'Belum pernah masuk';
</script>

<template>
  <Head title="Manajemen Pengguna" />
  <main class="min-h-screen px-5 py-7 md:px-8 md:py-9"><section class="mx-auto max-w-7xl">
    <header class="mb-7 flex flex-wrap items-end justify-between gap-5"><div>
      <nav aria-label="Breadcrumb" class="mb-3 flex items-center gap-2 text-xs font-bold text-emerald-100/85"><Link href="/admin/dashboard" class="transition hover:text-[#f0c959]">Dashboard</Link><span aria-hidden="true">/</span><span class="text-white">Pengguna</span></nav>
      <h1 class="text-3xl font-extrabold tracking-tight text-white md:text-4xl">Manajemen Pengguna</h1><p class="mt-2 max-w-2xl text-sm leading-6 text-emerald-50/80">Kelola akun tim, peran, dan akses untuk menjaga keamanan data PMB.</p>
    </div><div class="flex items-center gap-2 rounded-xl border border-[#f0c959]/35 bg-emerald-950/30 px-4 py-3 text-xs font-semibold text-emerald-50 backdrop-blur-sm"><svg class="h-4 w-4 text-[#f0c959]" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M19 8v6M22 11h-6" /></svg>{{ users.length }} pengguna terdaftar</div></header>
    <div v-if="flash?.success" role="status" class="mb-5 flex items-start gap-3 rounded-2xl border border-emerald-200 bg-emerald-50 px-5 py-4 text-sm font-semibold text-emerald-900 shadow-sm"><svg class="mt-0.5 h-5 w-5 shrink-0 text-emerald-700" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="m5 12 4 4L19 6" /></svg>{{ flash.success }}</div>
    <section aria-labelledby="add-user-title" class="rounded-[22px] border border-white/70 bg-white p-5 shadow-xl shadow-emerald-950/15 md:p-7"><div class="mb-6 flex flex-wrap items-start justify-between gap-3"><div><h2 id="add-user-title" class="text-xl font-extrabold text-[#103d31]">Tambah Pengguna Baru</h2><p class="mt-1 text-sm text-slate-500">Akun baru aktif setelah dibuat dan wajib mengganti kata sandi saat pertama masuk.</p></div><span class="text-xs font-semibold text-slate-500"><span class="text-rose-600">*</span> Wajib diisi</span></div>
      <div v-if="hasFormErrors" role="alert" class="mb-5 rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-800">Periksa kembali data yang diisi. Username dan email harus unik; kata sandi minimal 12 karakter serta mengandung huruf dan angka.</div>
      <form class="grid gap-x-5 gap-y-5 md:grid-cols-2 xl:grid-cols-3" @submit.prevent="submit">
        <label class="field"><span>Nama lengkap <b>*</b></span><input v-model="form.name" required autocomplete="name" maxlength="150" placeholder="Masukkan nama lengkap" :aria-invalid="!!form.errors.name" /><small v-if="form.errors.name">{{ form.errors.name }}</small></label>
        <label class="field"><span>Username <b>*</b></span><input v-model="form.username" required autocomplete="username" maxlength="50" pattern="[A-Za-z0-9_-]+" placeholder="contoh: admin_pmb" :aria-invalid="!!form.errors.username" /><small v-if="form.errors.username">{{ form.errors.username }}</small></label>
        <label class="field"><span>Email <b>*</b></span><input v-model="form.email" required type="email" autocomplete="email" maxlength="190" placeholder="nama@contoh.com" :aria-invalid="!!form.errors.email" /><small v-if="form.errors.email">{{ form.errors.email }}</small></label>
        <label class="field"><span>Peran <b>*</b></span><select v-model="form.role" required :aria-invalid="!!form.errors.role"><option v-for="role in roles" :key="role" :value="role">{{ roleLabels[role] }}</option></select><small v-if="form.errors.role">{{ form.errors.role }}</small></label>
        <label class="field"><span>Kata sandi <b>*</b></span><div class="password-input"><input v-model="form.password" required :type="showPassword?'text':'password'" autocomplete="new-password" minlength="12" placeholder="Minimal 12 karakter" :aria-invalid="!!form.errors.password" /><button type="button" :aria-label="showPassword?'Sembunyikan kata sandi':'Tampilkan kata sandi'" @click="showPassword=!showPassword">{{ showPassword?'Sembunyikan':'Tampilkan' }}</button></div><small v-if="form.errors.password">{{ form.errors.password }}</small></label>
        <label class="field"><span>Konfirmasi kata sandi <b>*</b></span><div class="password-input"><input v-model="form.password_confirmation" required :type="showConfirmation?'text':'password'" autocomplete="new-password" minlength="12" placeholder="Ulangi kata sandi" :aria-invalid="!!form.errors.password_confirmation" /><button type="button" :aria-label="showConfirmation?'Sembunyikan konfirmasi kata sandi':'Tampilkan konfirmasi kata sandi'" @click="showConfirmation=!showConfirmation">{{ showConfirmation?'Sembunyikan':'Tampilkan' }}</button></div><small v-if="form.errors.password_confirmation">{{ form.errors.password_confirmation }}</small></label>
        <div class="flex items-center justify-end gap-3 pt-1 md:col-span-2 xl:col-span-3"><button type="button" class="secondary-button" @click="resetForm">Batal</button><button type="submit" class="primary-button" :disabled="form.processing"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 4h11l3 3v13H5zM8 4v6h8V4M8 20v-6h8v6" /></svg>{{ form.processing?'Menyimpan…':'Simpan Pengguna' }}</button></div>
      </form>
    </section>
    <section aria-labelledby="user-list-title" class="mt-6 overflow-hidden rounded-[22px] border border-white/70 bg-white shadow-xl shadow-emerald-950/15"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-5 py-5 md:px-7"><div><h2 id="user-list-title" class="text-xl font-extrabold text-[#103d31]">Daftar Pengguna</h2><p class="mt-1 text-sm text-slate-500">Ubah nama, username, peran, atau status akun dari tabel berikut.</p></div><span class="rounded-full bg-emerald-50 px-3 py-1.5 text-xs font-bold text-emerald-800">{{ users.length }} akun</span></div><div class="overflow-x-auto"><table class="min-w-[940px] w-full text-left"><thead><tr><th>Pengguna</th><th>Peran</th><th>Status</th><th>Terakhir diperbarui</th><th class="text-right">Aksi</th></tr></thead><tbody>
      <tr v-for="user in users" :key="user.id"><td><div class="user-cell"><span class="avatar">{{ user.name.slice(0,2).toUpperCase() }}</span><div><input v-model="user.name" class="inline-edit name-edit" aria-label="Nama pengguna" /><div class="mt-1 flex items-center gap-2"><span class="text-xs text-slate-500">@</span><input v-model="user.username" class="inline-edit username-edit" aria-label="Username pengguna" /></div></div></div></td><td><select v-model="user.role" class="table-select" :aria-label="`Peran ${user.name}`"><option v-for="role in roles" :key="role" :value="role">{{ roleLabels[role] }}</option></select></td><td><label class="status-toggle"><input v-model="user.is_active" type="checkbox" /><span aria-hidden="true"></span><b>{{ user.is_active?'Aktif':'Nonaktif' }}</b></label></td><td><div class="text-sm font-medium text-slate-700">{{ formatDate(user.last_login_at) }}</div><div v-if="user.must_change_password" class="mt-1 text-xs text-amber-700">Wajib ganti kata sandi</div></td><td class="text-right"><button class="save-button" :disabled="savingUserId===user.id" @click="update(user)">{{ savingUserId===user.id?'Menyimpan…':'Simpan perubahan' }}</button></td></tr>
      <tr v-if="!users.length"><td colspan="5" class="px-7 py-12 text-center text-sm text-slate-500">Belum ada pengguna. Tambahkan akun pertama melalui formulir di atas.</td></tr></tbody></table></div></section>
  </section></main>
</template>

<style scoped>
.field{display:block;font-weight:700;color:#173c32}.field>span{display:block;margin-bottom:.5rem;font-size:.82rem}.field b{color:#e11d48}.field input,.field select,.password-input{width:100%;border:1px solid #cbd5e1;border-radius:.8rem;background:#fff;color:#334155;transition:border-color .15s,box-shadow .15s}.field input,.field select{min-height:2.9rem;padding:.65rem .8rem}.field input:focus,.field select:focus,.password-input:focus-within{border-color:#087154;outline:0;box-shadow:0 0 0 3px rgba(8,113,84,.12)}.field [aria-invalid="true"]{border-color:#e11d48}.field small{display:block;margin-top:.4rem;font-size:.73rem;font-weight:600;color:#be123c}.password-input{display:flex;align-items:center;overflow:hidden}.password-input input{min-width:0;border:0;padding-right:.25rem;box-shadow:none!important}.password-input button{margin-right:.35rem;flex:none;border:1px solid #e2e8f0;border-radius:.55rem;background:#fff;padding:.38rem .55rem;font-size:.72rem;font-weight:700;color:#334155}.primary-button,.secondary-button,.save-button{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;border-radius:.75rem;padding:.76rem 1rem;font-weight:800;transition:all .15s}.primary-button{background:#07583f;color:white;box-shadow:0 8px 16px rgba(6,78,59,.18)}.primary-button:hover:not(:disabled),.save-button:hover:not(:disabled){background:#087154}.secondary-button{border:1px solid #cbd5e1;background:white;color:#334155}.secondary-button:hover{background:#f8fafc}.primary-button:disabled,.save-button:disabled{cursor:wait;opacity:.65}thead{background:#043d2c;color:white}th{padding:1rem 1.2rem;font-size:.76rem;font-weight:800}td{padding:1rem 1.2rem;border-bottom:1px solid #e2e8f0;vertical-align:middle}tbody tr:last-child td{border-bottom:0}tbody tr:hover{background:#f8fffc}.user-cell{display:flex;align-items:center;gap:.8rem}.avatar{display:grid;width:2.6rem;height:2.6rem;place-items:center;border-radius:999px;background:#07583f;color:white;font-size:.75rem;font-weight:800}.inline-edit{border:1px solid transparent;border-radius:.5rem;background:transparent;padding:.25rem .35rem;font-weight:800;color:#173c32}.inline-edit:hover,.inline-edit:focus{border-color:#cbd5e1;background:white;outline:0}.name-edit{width:13rem}.username-edit{width:10rem;font-size:.78rem;font-weight:600;color:#64748b}.table-select{min-width:9.5rem;border:1px solid #cbd5e1;border-radius:.6rem;background:white;padding:.52rem .65rem;font-weight:700;color:#334155}.status-toggle{display:inline-flex;align-items:center;gap:.55rem;font-size:.8rem;color:#166534}.status-toggle input{position:absolute;opacity:0}.status-toggle span{position:relative;width:2.1rem;height:1.2rem;border-radius:99px;background:#cbd5e1;transition:.15s}.status-toggle span:after{position:absolute;top:.17rem;left:.18rem;width:.86rem;height:.86rem;border-radius:99px;background:white;content:'';transition:.15s}.status-toggle input:checked+span{background:#16a34a}.status-toggle input:checked+span:after{transform:translateX(.86rem)}.status-toggle input:focus-visible+span{outline:3px solid rgba(8,113,84,.2)}.save-button{background:#087154;color:white;font-size:.76rem}@media(max-width:640px){.name-edit{width:10rem}.secondary-button,.primary-button{flex:1}}
</style>
